<script setup lang="ts">
import {ref,watch} from 'vue'
import type {Filter,Taxonomy} from '../../shared/interfaces'
import {analysisLabels} from '../../shared/lib/processing'
const props=withDefaults(defineProps<{modelValue:Filter;taxonomy?:Taxonomy;callbackOnly?:boolean;resetKey?:number}>(),{taxonomy:()=>({tags:[],statuses:[]})})
const emit=defineEmits<{(e:'update:modelValue',value:Filter):void}>()
const validationError=ref('')
const tag=ref(''),status=ref(''),kind=ref(''),analysis=ref(''),callback=ref(false),hours=ref(2),noAttempts=ref(false)
function update(){validationError.value='';const rules:Filter[]=[];if(!props.callbackOnly){if(tag.value)rules.push({field:'tag_ids',op:'contains',value:tag.value});if(status.value)rules.push({field:'status_id',op:'eq',value:status.value});if(kind.value)rules.push({field:'contact_kind',op:'eq',value:kind.value});if(analysis.value)rules.push({field:'analysis_state',op:'eq',value:analysis.value})}if(callback.value){const h=Number(hours.value);if(hours.value===('' as unknown as number)||!Number.isFinite(h)||h<0||h>8760){validationError.value='Укажи интервал от 0 до 8760 часов';emit('update:modelValue',{op:'and',rules:[{field:'callback_age_minutes',op:'gte',value:NaN}]});return}validationError.value='';rules.push({field:'callback_state',op:'in',value:['open','overdue']},{field:'callback_age_minutes',op:'gte',value:Math.round(h*60*1e6)/1e6});if(noAttempts.value)rules.push({field:'callback_attempts',op:'eq',value:0})}emit('update:modelValue',{op:'and',rules})}
watch(()=>props.resetKey,()=>{tag.value='';status.value='';kind.value='';analysis.value='';callback.value=false;hours.value=2;noAttempts.value=false;emit('update:modelValue',{op:'and',rules:[]})})
</script>
<template><div class="workspace-filters"><div v-if="!callbackOnly" class="workspace-filter-selects"><label>Тег<select v-model="tag" aria-label="Фильтр по тегу" @change="update"><option value="">Все теги</option><option v-for="item in taxonomy.tags" :key="item.id" :value="item.id">{{item.name}}{{item.archived?' (архив)':''}}</option></select></label><label>Бизнес-статус<select v-model="status" aria-label="Фильтр по бизнес-статусу" @change="update"><option value="">Все статусы</option><option v-for="item in taxonomy.statuses" :key="item.id" :value="item.id">{{item.name}}{{item.archived?' (архив)':''}}</option></select></label><label>Тип обращения<select v-model="kind" aria-label="Фильтр по типу обращения" @change="update"><option value="">Любой тип</option><option value="primary">Первичное</option><option value="repeat">Повторное</option><option value="unknown">Не определено</option></select></label><label>Анализ<select v-model="analysis" aria-label="Фильтр по анализу" @change="update"><option value="">Любое состояние</option><option v-for="(label,value) in analysisLabels" :key="value" :value="value">{{label}}</option></select></label></div><div class="callback-filter"><label class="checkbox"><input v-model="callback" type="checkbox" aria-label="Без успешного перезвона" @change="update"/>Без успешной связи не менее</label><label class="callback-hours"><input v-model.number="hours" type="number" min="0" max="8760" step="any" aria-label="Интервал без перезвона, часов" :disabled="!callback" @input="update"/>часов</label><label v-if="callback" class="checkbox"><input v-model="noAttempts" type="checkbox" aria-label="Без попыток перезвона" @change="update"/>Не было попыток дозвона</label></div><p v-if="validationError" class="processing-error" role="alert">{{validationError}}</p><p v-if="callback" class="filter-explanation">Плавающий интервал от первого пропущенного обращения; без подтверждённого разговора. Неполная история остаётся отдельным состоянием в контроле перезвонов.</p></div></template>
